const fs=require('node:fs');const z=require('node:zlib');
const f=process.argv[1];
const chunks=[];const dec=z.createZstdDecompress();
dec.on('data',c=>chunks.push(c));
dec.on('end',()=>{const t=Buffer.concat(chunks).toString('utf8');
 const lines=t.split('\n').filter(Boolean);console.log('lines',lines.length);
 const counts=new Map();
 for(const l of lines){let e;try{e=JSON.parse(l)}catch{continue}
  const ty=e.type||'?';counts.set(ty,(counts.get(ty)||0)+1);}
 for(const [k,v] of [...counts].sort())console.log(k,v);
 fs.writeFileSync('approval-events.ndjson',t);
});
dec.on('error',e=>{console.error('ERR',e);process.exit(1)});
fs.createReadStream(f).pipe(dec);
